import axios from "axios";
import React, { useState } from "react";
import { Form } from "react-bootstrap";
import { useNavigate } from "react-router-dom";

function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [errorMsg, setErrorMsg] = useState("");
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const logRes = await axios.get(
        `http://localhost:9999/accounts?email=${email}&password=${password}`,
      );
      if (logRes.data.length > 0) {
        const user = logRes.data[0];
        if (user.status === "Inactive") {
          setErrorMsg("tai khoan bi khoa");
        } else {
          localStorage.setItem("user", JSON.stringify(user));
          navigate("/syllabus");
        }
      } else {
        setErrorMsg("sai email or password");
      }
    } catch (error) {
      console.log("loi khi tai du lieu", error);
    }
  };

  return (
    <div>
      <div
        className="container"
        style={{
          border: "1px solid black",
          width: "300px",
          marginTop: "200px",
          borderRadius: "10px",
          padding: "50px",
        }}
      >
        <h3 style={{ textAlign: "center", padding: "10px" }}>Sign In</h3>
        <Form onSubmit={handleLogin}>
          <div>
            <input
              style={{ padding: "10px", width: "200px", marginBottom: "10px" }}
              type="text"
              placeholder="email of student or lecture"
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <input
              style={{ padding: "10px", width: "200px", marginBottom: "10px" }}
              type="text"
              placeholder="Enter password"
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          {errorMsg && <p>{errorMsg}</p>}
          <button
            style={{
              width: "200px",
              marginBottom: "10px",
              border: "0px",
              background: "#d328a0",
              color: "white",
              padding: "10px",
              borderRadius: "8px",
              fontWeight: "bold",
            }}
          >
            Login
          </button>
        </Form>
      </div>
    </div>
  );
}

export default Login;
